CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS app_state (id smallint PRIMARY KEY DEFAULT 1 CHECK(id=1), payload jsonb NOT NULL DEFAULT '{}'::jsonb, updated_at timestamptz NOT NULL DEFAULT now(), updated_by uuid);
CREATE TABLE IF NOT EXISTS app_storage (key text PRIMARY KEY, value text, updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS users (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), username varchar(80) UNIQUE NOT NULL, full_name varchar(180) NOT NULL, password_hash text NOT NULL, role varchar(30) NOT NULL DEFAULT 'USER', active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
ALTER TABLE app_state DROP CONSTRAINT IF EXISTS app_state_updated_by_fkey; ALTER TABLE app_state ADD CONSTRAINT app_state_updated_by_fkey FOREIGN KEY(updated_by) REFERENCES users(id);
CREATE TABLE IF NOT EXISTS audit_log (id bigserial PRIMARY KEY, user_id uuid REFERENCES users(id), username varchar(80), module varchar(80), action varchar(40), record_key text, changed_at timestamptz NOT NULL DEFAULT now(), details jsonb NOT NULL DEFAULT '{}'::jsonb);
CREATE TABLE IF NOT EXISTS products (code varchar(100) PRIMARY KEY, parent_code varchar(100), product_type varchar(20), description text, unit varchar(30), payload jsonb NOT NULL DEFAULT '{}'::jsonb, updated_at timestamptz NOT NULL DEFAULT now(), updated_by uuid REFERENCES users(id));
CREATE TABLE IF NOT EXISTS materials (code varchar(100) PRIMARY KEY, description text, unit varchar(30), payload jsonb NOT NULL DEFAULT '{}'::jsonb, updated_at timestamptz NOT NULL DEFAULT now(), updated_by uuid REFERENCES users(id));
CREATE TABLE IF NOT EXISTS suppliers (code varchar(100) PRIMARY KEY, name text, tax_id varchar(40), payload jsonb NOT NULL DEFAULT '{}'::jsonb, updated_at timestamptz NOT NULL DEFAULT now(), updated_by uuid REFERENCES users(id));
CREATE TABLE IF NOT EXISTS equipment (code varchar(100) PRIMARY KEY, name text, process text, active boolean NOT NULL DEFAULT true, payload jsonb NOT NULL DEFAULT '{}'::jsonb, updated_at timestamptz NOT NULL DEFAULT now(), updated_by uuid REFERENCES users(id));
CREATE TABLE IF NOT EXISTS equipment_documents (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), equipment_code varchar(100) NOT NULL REFERENCES equipment(code) ON DELETE CASCADE, original_name text NOT NULL, stored_name text NOT NULL, mime_type text, file_size bigint, document_type varchar(80), revision varchar(40), active boolean NOT NULL DEFAULT true, uploaded_at timestamptz NOT NULL DEFAULT now(), uploaded_by uuid REFERENCES users(id));
CREATE TABLE IF NOT EXISTS routes (code varchar(100) PRIMARY KEY, product_code varchar(100), version varchar(50), payload jsonb NOT NULL DEFAULT '{}'::jsonb, updated_at timestamptz NOT NULL DEFAULT now(), updated_by uuid REFERENCES users(id));
CREATE TABLE IF NOT EXISTS route_steps (id bigserial PRIMARY KEY, route_code varchar(100) NOT NULL REFERENCES routes(code) ON DELETE CASCADE, step_order numeric, process text, equipment_code varchar(100), payload jsonb NOT NULL DEFAULT '{}'::jsonb);
CREATE TABLE IF NOT EXISTS production_orders (code varchar(120) PRIMARY KEY, product_code varchar(100), parent_op varchar(120), route_code varchar(100), status varchar(50), planned_qty numeric, unit varchar(30), payload jsonb NOT NULL DEFAULT '{}'::jsonb, updated_at timestamptz NOT NULL DEFAULT now(), updated_by uuid REFERENCES users(id));
CREATE TABLE IF NOT EXISTS op_steps (id bigserial PRIMARY KEY, op_code varchar(120) NOT NULL REFERENCES production_orders(code) ON DELETE CASCADE, step_order numeric, process text, equipment_code varchar(100), payload jsonb NOT NULL DEFAULT '{}'::jsonb);
CREATE TABLE IF NOT EXISTS op_materials (id bigserial PRIMARY KEY, op_code varchar(120) NOT NULL REFERENCES production_orders(code) ON DELETE CASCADE, material_code varchar(100), consumed_pi_code varchar(100), step_order numeric, planned_qty numeric, unit varchar(30), lot text, payload jsonb NOT NULL DEFAULT '{}'::jsonb);
CREATE TABLE IF NOT EXISTS op_document_flags (op_code varchar(120) NOT NULL REFERENCES production_orders(code) ON DELETE CASCADE, document_id uuid NOT NULL REFERENCES equipment_documents(id) ON DELETE CASCADE, include_print boolean NOT NULL DEFAULT true, PRIMARY KEY(op_code,document_id));
CREATE TABLE IF NOT EXISTS icv_snapshots (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), op_code varchar(120) REFERENCES production_orders(code), scenario text, payload jsonb NOT NULL, active_for_passport boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), created_by uuid REFERENCES users(id));
CREATE TABLE IF NOT EXISTS aicv_results (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), icv_id uuid REFERENCES icv_snapshots(id) ON DELETE CASCADE, indicator text, unit text, value numeric, payload jsonb NOT NULL DEFAULT '{}'::jsonb);
CREATE TABLE IF NOT EXISTS lcc_studies (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), op_code varchar(120) REFERENCES production_orders(code), scenario text, payload jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), created_by uuid REFERENCES users(id));
CREATE TABLE IF NOT EXISTS battery_passports (id text PRIMARY KEY, op_code varchar(120) REFERENCES production_orders(code), product_code varchar(100), payload jsonb NOT NULL DEFAULT '{}'::jsonb, updated_at timestamptz NOT NULL DEFAULT now(), updated_by uuid REFERENCES users(id));
CREATE INDEX IF NOT EXISTS idx_audit_changed_at ON audit_log(changed_at DESC); CREATE INDEX IF NOT EXISTS idx_docs_equipment ON equipment_documents(equipment_code); CREATE INDEX IF NOT EXISTS idx_op_parent ON production_orders(parent_op); CREATE INDEX IF NOT EXISTS idx_icv_op ON icv_snapshots(op_code);
